import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { booksAPI } from '../utils/api';

const LandingPage = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalBooks: 0,
    target: 100000,
    percentageComplete: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchGlobalStats();
    // Refresh stats every 30 seconds
    const interval = setInterval(fetchGlobalStats, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchGlobalStats = async () => {
    try {
      const response = await booksAPI.getGlobalStats();
      setStats(response.data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching stats:', error);
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="header">
        <div className="header-content">
          <h1>🎓 AKHSS Kharadar - 100 Years Celebration</h1>
          <p>Gift of Reading Initiative</p>
          <p style={{ fontSize: '0.9rem', marginTop: '5px', fontStyle: 'italic' }}>
            Aligned with the guidance of His Highness the Aga Khan V
          </p>
        </div>
      </div>

      <div className="container">
        <div className="card" style={{ textAlign: 'center' }}>
          <div style={{ 
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            padding: '40px',
            borderRadius: '15px',
            marginBottom: '30px'
          }}>
            <h2 style={{ fontSize: '2.5rem', marginBottom: '15px' }}>
              📚 Join Our Reading Journey
            </h2>
            <p style={{ fontSize: '1.2rem', lineHeight: '1.8' }}>
              Be part of history! Help the entire AKESP community achieve our collective goal 
              of completing <strong>100,000 book readings</strong> to celebrate 100 years 
              of educational excellence.
            </p>
          </div>

          <div style={{ marginBottom: '40px' }}>
            <h3 style={{ marginBottom: '20px', color: '#333' }}>
              How It Works
            </h3>
            <div style={{ 
              display: 'grid', 
              gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
              gap: '20px',
              textAlign: 'left'
            }}>
              <div style={{ padding: '20px', background: '#f8f9fa', borderRadius: '10px' }}>
                <div style={{ fontSize: '2rem', marginBottom: '10px' }}>1️⃣</div>
                <h4>Register</h4>
                <p>Create your account using your B-Form or CNIC number</p>
              </div>
              <div style={{ padding: '20px', background: '#f8f9fa', borderRadius: '10px' }}>
                <div style={{ fontSize: '2rem', marginBottom: '10px' }}>2️⃣</div>
                <h4>Read</h4>
                <p>Read books of your choice and enjoy the journey</p>
              </div>
              <div style={{ padding: '20px', background: '#f8f9fa', borderRadius: '10px' }}>
                <div style={{ fontSize: '2rem', marginBottom: '10px' }}>3️⃣</div>
                <h4>Record</h4>
                <p>Log each book you complete on our portal</p>
              </div>
              <div style={{ padding: '20px', background: '#f8f9fa', borderRadius: '10px' }}>
                <div style={{ fontSize: '2rem', marginBottom: '10px' }}>4️⃣</div>
                <h4>Celebrate</h4>
                <p>Watch our community progress toward 100,000 books!</p>
              </div>
            </div>
          </div>

          <div style={{ display: 'flex', gap: '15px', justifyContent: 'center', flexWrap: 'wrap' }}>
            <button 
              className="btn" 
              onClick={() => navigate('/register')}
              style={{ fontSize: '1.1rem', padding: '15px 40px' }}
            >
              🚀 Start the Journey
            </button>
            <button 
              className="btn btn-secondary" 
              onClick={() => navigate('/login')}
              style={{ fontSize: '1.1rem', padding: '15px 40px' }}
            >
              🔑 Already Registered? Login
            </button>
          </div>
        </div>

        <div className="card">
          <h2 style={{ textAlign: 'center', marginBottom: '30px', color: '#333' }}>
            📊 Pledge Live Tracker
          </h2>
          
          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
              <p>Loading statistics...</p>
            </div>
          ) : (
            <>
              <div style={{ textAlign: 'center', marginBottom: '30px' }}>
                <div style={{ 
                  display: 'inline-block',
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  padding: '40px',
                  borderRadius: '50%',
                  width: '220px',
                  height: '220px',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  boxShadow: '0 10px 30px rgba(0, 0, 0, 0.2)'
                }}>
                  <div style={{ fontSize: '3rem', fontWeight: 'bold' }}>
                    {stats.totalBooks.toLocaleString()}
                  </div>
                  <div style={{ fontSize: '1rem', marginTop: '10px' }}>
                    of {stats.target.toLocaleString()}
                  </div>
                  <div style={{ fontSize: '0.9rem', marginTop: '5px', opacity: 0.9 }}>
                    books read
                  </div>
                </div>
              </div>

              <div style={{ marginBottom: '20px' }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  marginBottom: '10px',
                  fontSize: '1.1rem',
                  fontWeight: 'bold',
                  color: '#333'
                }}>
                  <span>Progress</span>
                  <span>{stats.percentageComplete}%</span>
                </div>
                <div className="progress-bar">
                  <div 
                    className="progress-fill" 
                    style={{ width: `${Math.min(stats.percentageComplete, 100)}%` }}
                  >
                    {stats.percentageComplete > 5 && `${stats.percentageComplete}%`}
                  </div>
                </div>
              </div>

              <div style={{ 
                textAlign: 'center', 
                padding: '20px',
                background: '#f8f9fa',
                borderRadius: '10px',
                marginTop: '30px'
              }}>
                <p style={{ fontSize: '1.2rem', color: '#666' }}>
                  🌟 Together, we're making a difference! 
                  {stats.totalBooks > 0 && ` Join ${stats.totalUsers} readers who have already contributed!`}
                </p>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
